\begin{equation} \label{eq:PD_problem}
\left.
\begin{aligned}
    \inf\;\, & \mathbf{c}^\top \mathbf{x} \\
    \st\  & A\mathbf{x} = \mathbf{b} \\
    & \mathbf{x} \in \mathcal{K}
\end{aligned}
\quad \right\} \quad \text{(P)}
\qquad \qquad \qquad \left.
\begin{aligned}
    \sup \;\, & \mathbf{b}^\top \mathbf{y} \\
    \st\;\; & A^\top \mathbf{y} + \mathbf{s} = \mathbf{c} \\
    & \mathbf{s} \in \mathcal{K}^*, \  \mathbf{y} \in \mathbb{R}^m \\
\end{aligned}
\quad \right\}  \quad\text{(D)}
\end{equation}

where $\mathbf{c} \in \mathbb{R}^n$ and $\mathbf{b} \in \mathbb{R}^m$ are given vectors, $A \in \mathbb{R}^{m \times n}$ is a given matrix with full row rank, and $\mathcal{K} \subseteq \mathbb{R}^n$ is a proper convex cone whose dual cone is denoted by $\mathcal{K}^*$. The only assumption we make about $\K$ is that its interior, denoted by $\K^\circ$, is the domain of a known logarithmically homogeneous self-concordant barrier function (LHSCB), see Appendix \ref{sec:lhscb}, whose gradient and Hessian are computable efficiently. The cone need not have any other desirable properties; in particular, we do not assume that $\K$ is symmetric, homogeneous, or hyperbolic. Nor do we make any assumptions about its dual.


Let $\mathcal{F}$ denote the set of primal-dual feasible solutions:
\[
\mathcal{F} = \left\{ (\mathbf{x}, \mathbf{y}, \mathbf{s})\in\mathcal{K}\times\mathbb{R}^m\times\mathcal{K}^* \mid A\mathbf{x} = \mathbf{b}, \ A^{\top}\mathbf{y} + \mathbf{s} = \mathbf{c} \right\},
\]

and let $\mathcal{F}^{\circ}$ be the set of strictly feasible solutions:
\[
\mathcal{F}^{\circ} = \left\{ (\mathbf{x}, \mathbf{y}, \mathbf{s})\in\mathcal{K}^\circ\times\mathbb{R}^m\times(\mathcal{K}^*)^\circ \mid A\mathbf{x} = \mathbf{b}, \ A^{\top}\mathbf{y} + \mathbf{s} = \mathbf{c} \right\}.
\]

Suppose that the interior point (aka.~Slater) condition is satisfied: $\mathcal{F}^{\circ} \neq \emptyset$. Then strong duality holds, and the optimality conditions can be formulated as
\begin{equation}
\left.
\begin{aligned}
(\vx,\vy,\vs)&\in\mathcal{F}\\
\vx^\T\vs&=0
\end{aligned} \right\}. \tag{OC}\label{eq:OC}
\end{equation}

We assume that an LHSCB $f: \mathcal{K}^{\circ} \rightarrow \mathbb{R}$ with barrier parameter $\nu$ is given for the primal cone $\mathcal{K}$. Let $g(\mathbf{x})$ and $H(\mathbf{x})$ denote the gradient and Hessian of $f$ at $\mathbf{x} \in \mathcal{K}^{\circ}$, respectively. With this notation in place, we define the central path problem, parametrized by the positive scalar $\tau$, called the \emph{central path parameter}, as follows:
\begin{equation}
\left.
\begin{aligned}
(\vx,\vy,\vs)&\in\mathcal{F}^\circ\\
    \mathbf{s} + \tau g(\mathbf{x}) \ & = \mathbf{0} \\
\end{aligned} \right\}. \tag{CP}\label{eq:CP}
\end{equation}

In the analysis,  we consider the following \emph{neighborhood} of the central path:
\begin{equation}
\label{eq:nbd}
\mathcal{N}(\eta,\tau) = \left\{ (\mathbf{x}, \mathbf{y}, \mathbf{s}) \in \mathcal{F}^\circ : \| \mathbf{s} + \tau g(\mathbf{x}) \|_{\mathbf{x}}^* \leq \eta \tau \right\},
\end{equation}

Given an $(\mathbf{x},\mathbf{y},\mathbf{s})\in\mathcal{F}^\circ$, the \emph{Newton system} associated with the central path \eqref{eq:CP} is
\begin{equation}
\left.
\begin{aligned}
    A \Delta \mathbf{x} & = \mathbf{0} \\
    A^{\top} \Delta \mathbf{y} + \Delta \mathbf{s} & = \mathbf{0} \\
    \tau H(\mathbf{x}) \Delta \mathbf{x} + \Delta \mathbf{s} & = -(\mathbf{s} + \tau g(\mathbf{x}))
\end{aligned} \right\} .
\tag{NS}\label{eq:NS}
\end{equation}

Its solution ($\Delta \mathbf{x}$, $\Delta \mathbf{y}$, $\Delta \mathbf{s}$)
is called the \emph{Newton direction} at $(\vx,\vy,\vs)$.


\begin{algorithm}[h]
\caption{A full-step IPA for nonsymmetric cone programming}
\label{alg:simple_short_step}
\begin{algorithmic}
\vspace{0.5em}
\STATE \textbf{inputs:}
$A \in \mathbb{R}^{m \times n}$ with full row rank; $\mathbf{b} \in \mathbb{R}^m$;  $\mathbf{c} \in \mathbb{R}^n$;
\\ \hspace{1em}an oracle for computing the Hessian $H$ of the $\nu$-LHSCB $f: \ \mathcal{K}^{\circ} \rightarrow \mathbb{R}$;
\\ \hspace{1em}an initial $\tau_0>0$ and
$(\mathbf{x}_0, \mathbf{y}_0, \mathbf{s}_0) \in \mathcal{F}^\circ$ such that $\| \mathbf{s}_0 + \tau_0 g(\mathbf{x}_0) \|_{\mathbf{x}_0}^* \leq \eta \tau_0$;
\\ \hspace{1em}$\varepsilon > 0$ optimality tolerance.

\vspace{0.5em}
\STATE \textbf{parameters:}
neighborhood parameter $\eta \in (0, 1)$;
update parameter $\vartheta$.
\vspace{0.5em}

\STATE \textbf{output:} a triplet $(\vx,\vy,\vs)\in\mathcal{F}^\circ$ satisfying $\vx^\T\vs\leq\varepsilon$.

\vspace{1em}
\STATE Initialize $\mathbf{x} := \mathbf{x}_0$, $\mathbf{y} := \mathbf{y}_0$, $\mathbf{s} := \mathbf{s}_0$, $\tau := \tau_0$.
\vspace{0.5em}
\WHILE{$\mathbf{x}^\top \mathbf{s} > \varepsilon$}
    \STATE Solve \eqref{eq:NS} for $(\Delta \mathbf{x}, \Delta \mathbf{y}, \Delta \mathbf{s})$.
    \STATE Set $\mathbf{x} := \mathbf{x} + \Delta \mathbf{x}$, $\mathbf{y} := \mathbf{y} + \Delta \mathbf{y}$, $\mathbf{s} := \mathbf{s} + \Delta \mathbf{s}$.
    \STATE Set $\tau := (1 - \vartheta) \tau$.
\ENDWHILE
\vspace{0.5em}
\STATE \textbf{return} $(\mathbf{x}, \mathbf{y}, \mathbf{s})$.
\vspace{0.5em}
\end{algorithmic}
\end{algorithm}

\begin{definition}[Self-concordant barrier]
Let $\K\subseteq\Rn$ be a convex cone with a non-empty interior $\K^\circ$. A function $f:\K^\circ\to\R$ is called a \emph{strongly nondegenerate, self-concordant barrier} for $\K$ if $f$ is strictly convex, at least three times differentiable, and has the following two properties (with $\operatorname{bd}(\K)$ denoting the boundary of $\K$, and $g$ and $H$ denoting the gradient and Hessian of $f$):
\begin{enumerate}[\hspace{1em} 1.]
\item $f(\vx)\to\infty$  as $\vx\to\operatorname{bd}(\K)$,
\item $|D^3 f(\vx)[\vh,\vh,\vh]| \leq 2\left(D^2f(\vx)[\vh,\vh]\right)^{3/2}$,
\item $\nu := \sup_{\vx\in\K^\circ} g(\vx)^\T H(\vx)^{-1}g(\vx) < \infty.$
\end{enumerate}
We refer to the parameter $\nu$ above as the \emph{barrier parameter} of $f$; we also use the shorthand \emph{$\nu$-SCB} to mean ``an SCB with barrier parameter $\nu$''.
\end{definition}

\begin{definition}[Logarithmic homogeneity and LHSCBs]
    Let $f: \ \mathcal{K}^{\circ} \rightarrow \mathbb{R}$ be a $\nu$-SCB function for the proper convex cone $ \mathcal{K}$.  We say that $f$ is a \emph{logarithmically homogeneous self-concordant barrier (LHSCB)} with barrier parameter $\nu$ for $\mathcal{K}$, or a \emph{$\nu$-LHSCB} for short, if it satisfies the \emph{logarithmic homogeneity property}
    \[ f(t \mathbf{x}) = f(\mathbf{x}) - \nu \ln (t) \quad \text{for all } \mathbf{x} \in \mathcal{K}^{\circ} \text{ and } t > 0.\]
\end{definition}

We associate with each $\vx\in\K^\circ$ the \emph{local inner product} $\langle\cdot,\cdot\rangle_\vx : \K \times \K \to \R$ defined as $\langle \vu,\vv\rangle_\vx := \vu^\T H(\vx) \vv$ and the \emph{local norm} $\|\cdot\|_\vx$ induced by this local inner product. Thus, $\|\vv\|_\vx = \|H(\vx)^{1/2}\vv\|$. We define the local (open) ball centered at $\vx$ with radius $r$ by $\mathcal{B}(\vx,r) := \{\vv\in\R^n\,|\, \|\vv-\vx\|_{\vx} < r\}$. When $r=1$, these balls are also called the \emph{Dikin ellipsoids}. Crucially, for every $\vx\in\K^\circ$, we have $\mathcal{B}(\vx,1)\subset\K^\circ$.

Analogously, we define the \emph{dual local inner product} $\langle \cdot,\cdot \rangle_\vx^*: \K^*\times\K^*\to\R$ by  $\langle \vs, \vt \rangle_\vx^* := \vs^\T H(\vx)^{-1}\vt$, its induced \emph{dual local norm} $\|\cdot\|_{\vx}^*$, and the corresponding open balls $\mathcal{B}^*(\vx,r)$. The dual local norm, by definition, satisfies the identity $\|\vt\|_{\vx}^* = \|H(\vx)^{-1/2}\vt\|$.

