\begin{lemma}[\cite{PappYildiz2017, Serrano2015,SkajaaYe2015}]\label{lemma:sd_properties}
Let $(\mathbf{x}, \mathbf{y}, \mathbf{s}) \in \mathcal{N}(\eta, \tau)$ and let $(\Delta \mathbf{x}, \Delta \mathbf{y}, \Delta \mathbf{s})$ be the solution of \eqref{eq:NS}. Then
\begin{enumerate}[label=(\roman*)]
    \item  $\Delta \mathbf{x}^{\top} \Delta \mathbf{s} = 0$, \label{sd_prop:first}
    \item $
\| \Delta \mathbf{x} \|_{\mathbf{x}} \leq \eta$ and $\| \Delta \mathbf{s} \|_{\mathbf{x}}^* \leq \eta \tau
$,  \label{sd_prop:second}
    \item $\| \mathbf{s} + \tau g(\mathbf{x}) + \Delta \mathbf{s} \|_{\mathbf{x}}^* \leq \eta \tau$. \label{sd_prop:third}
\end{enumerate}
\end{lemma}

\begin{proof}
    \begin{enumerate}[label=(\roman*)]
        \item Using the first two equations of \eqref{eq:NS}, we get
    \[ 0 = \Delta \mathbf{x}^{\top} (A^{\top} \Delta \mathbf{y} + \Delta \mathbf{s}) = \Delta \mathbf{y}^{\top} A \Delta \mathbf{x} + \Delta \mathbf{x}^{\top} \Delta \mathbf{s} = \Delta \mathbf{x}^{\top} \Delta \mathbf{s}. \]
        \item Using the neighborhood definition, the orthogonality of $\Delta \mathbf{x}$ and $\Delta \mathbf{s}$, and the third equality of the Newton system, we can derive the upper bounds the following way:
\[ \begin{aligned}
\eta^2 \tau^2 &\geq \left( \| \mathbf{s} + \tau g(\mathbf{x}) \|_{\mathbf{x}}^* \right)^2 = \left( \| \tau H(\mathbf{x}) \Delta \mathbf{x} + \Delta \mathbf{s} \|_{\mathbf{x}}^* \right)^2 \\
&= \tau^2 \Delta \mathbf{x}^\top H(\mathbf{x}) \Delta \mathbf{x} + \Delta \mathbf{s}^\top H(\mathbf{x})^{-1} \Delta \mathbf{s}
= \tau^2 \| \Delta \mathbf{x} \|_{\mathbf{x}}^2 + (\| \Delta \mathbf{s} \|_{\mathbf{x}}^*)^2.
\end{aligned}
\]

As both terms on the right-hand side are nonnegative, it follows that $\| \Delta \mathbf{x} \|_{\mathbf{x}} \leq \eta$ and $\| \Delta \mathbf{s} \|_{\mathbf{x}}^* \leq \eta \tau$.
    \item Using the third equation of \eqref{eq:NS} and the upper bound on $\|\Delta \mathbf{x}\|_{\mathbf{x}}$ from \ref{sd_prop:second}, we get
    \[
\| \mathbf{s} + \tau g(\mathbf{x}) + \Delta \mathbf{s} \|_{\mathbf{x}}^* = \| \tau H(\mathbf{x}) \Delta \mathbf{x} \|_{\mathbf{x}}^*
= \tau \| \Delta \mathbf{x} \|_{\mathbf{x}} \leq \eta \tau.
  \]

    \end{enumerate}
\end{proof}

\begin{lemma}
\label{lemma:zplus-in-Nthetaplus}
Let $(\mathbf{x}, \mathbf{y}, \mathbf{s}) \in \mathcal{N}(\eta, \tau)$, let $(\Delta \mathbf{x}, \Delta \mathbf{y}, \Delta \mathbf{s})$ be the solution of \eqref{eq:NS}, and let $(\mathbf{x}^+, \mathbf{y}^+, \mathbf{s}^+) = (\mathbf{x}, \mathbf{y}, \mathbf{s}) + (\Delta \mathbf{x}, \Delta \mathbf{y}, \Delta \mathbf{s})$. If $0 < \eta \leq \frac{1}{4}$ and $
\vartheta = \frac{\eta / 2}{\sqrt{\nu} + 1}$,
then the new point satisfies $(\mathbf{x}^+, \mathbf{y}^+, \mathbf{s}^+) \in \mathcal{N}(\eta, \tau^+)$ with $\tau^+ = (1 - \vartheta) \tau$.
\end{lemma}

\begin{proof}
    Let us define the function $\varphi : \mathcal{K}^\circ \to \mathbb{R}$:
\[
\varphi(\mathbf{v}) = \frac{1}{\tau} (\mathbf{s} + \Delta \mathbf{s})^\top \mathbf{v} + f(\mathbf{v}),
\]
where $f$ is the known LHSCB for $\mathcal{K}^\circ$, with gradient $g$ and Hessian $H$.

Then $\varphi$ is self-concordant, and its Hessian is also $H$.
Let $\mathbf{n}_{\varphi}(\mathbf{v})$ denote the (unconstrained) Newton step for $\varphi$ at $\mathbf{v} \in \mathcal{K}^\circ$:
\[
\mathbf{n}_{\varphi}(\mathbf{v}) = -\tau^{-1} H(\mathbf{v})^{-1} \left( \mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{v}) \right).
\]
Thus,
\[
\mathbf{n}_{\varphi}(\mathbf{x}) = -\tau^{-1} H(\mathbf{x})^{-1} \left( \mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{x}) \right) = \Delta \mathbf{x},
\]
and therefore,
\[
\mathbf{x}^+ = \mathbf{x} + \Delta \mathbf{x} = \mathbf{x} + \mathbf{n}_{\varphi}(\mathbf{x}).
\]

For any $\mathbf{v} \in \mathcal{K}^\circ$,
\[
\|\mathbf{n}_{\varphi}(\mathbf{v})\|_{\mathbf{v}} = \left\| \tau^{-1} H(\mathbf{v})^{-1} \left( \mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{v}) \right) \right\|_{\mathbf{v}}
= \tau^{-1} \|\mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{v})\|_{\mathbf{v}}^*.
\]
For $\mathbf{v} = \mathbf{x}$, $\|\mathbf{n}_{\varphi}(\mathbf{x})\|_{\mathbf{x}} = \|\Delta \mathbf{x}\|_{\mathbf{x}} \leq \eta$, using Lemma \ref{lemma:sd_properties}, part \ref{sd_prop:second}. As $\eta < 1$, we can use \ref{prop:scb_NS}:
\begin{equation} \label{eq:UB_NS}
    \tau^{-1} \|\mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{x}^+)\|^*_{\mathbf{x}^+} = \|\mathbf{n}_{\varphi}(\mathbf{x}^+)\|_{\mathbf{x}^+}
\leq \left( \frac{\|\mathbf{n}_{\varphi}(\mathbf{x})\|_{\mathbf{x}}}{1 - \|\mathbf{n}_{\varphi}(\mathbf{x})\|_{\mathbf{x}}} \right)^2 \leq \frac{\eta^2}{(1 - \eta)^2}.
\end{equation}

Thus,
\begin{align*}
\frac{1}{\tau^+} \left\| \mathbf{s}^+ + \tau^+ g(\mathbf{x}^+) \right\|_{\mathbf{x}^+}^*
&= \frac{1}{1 - \vartheta} \tau^{-1} \| \mathbf{s} + \Delta \mathbf{s} + \tau^+ g(\mathbf{x}^+) \|_{\mathbf{x}^+}^* \\
&\leq \frac{1}{1 - \vartheta} \tau^{-1} \| \mathbf{s} + \Delta \mathbf{s} + \tau g(\mathbf{x}^+)\|_{\mathbf{x}^+}^* + \frac{\vartheta}{1 - \vartheta} \| g(\mathbf{x}^+) \|^*_{\mathbf{x}^+} \\
&\stackrel{\eqref{eq:UB_NS},\ref{prop:lhscb_norm}}{\leq} \frac{1}{1 - \vartheta}  \frac{\eta^2}{(1 - \eta)^2} + \frac{\vartheta}{1 - \vartheta} \sqrt{\nu} \\
&= \frac{\sqrt{\nu} + 1}{\sqrt{\nu} + 1 - \eta/2} \cdot \frac{\eta^2}{(1 - \eta)^2} + \frac{\eta / 2}{\sqrt{\nu} + 1 - \eta/2} \sqrt{\nu} \\
&\leq \frac{2}{2 - \eta / 2} \cdot \frac{\eta^2}{(1 - \eta)^2} + \frac{\eta}{2}.
\end{align*}

The last expression is less than $\eta$ if $\eta \leq \frac{1}{4}$ holds.
\end{proof}

\begin{lemma} \label{lemma:DG}
Let $(\mathbf{x}, \mathbf{y}, \mathbf{s}) \in \mathcal{N}(\eta, \tau)$ and let $(\Delta \mathbf{x}, \Delta \mathbf{y}, \Delta \mathbf{s})$ be the solution of \eqref{eq:NS}. We have the following lower and upper bounds on the duality gap after a full Newton step:
    \[ \tau(\nu - \eta^2) \leq (\mathbf{x}^+)^\top \mathbf{s}^+ \leq \tau \nu. \]
\end{lemma}

\begin{proof}
Using \ref{sd_prop:first} from Lemma \ref{lemma:sd_properties},
    \[ (\mathbf{x}^+)^\top \mathbf{s}^+ = (\mathbf{x} + \Delta \mathbf{x})^\top (\mathbf{s} + \Delta \mathbf{s}) = \mathbf{x}^\top \mathbf{s} + \mathbf{s}^\top \Delta \mathbf{x} + \mathbf{x}^\top \Delta \mathbf{s}. \]
From the third equation of \eqref{eq:NS}, we have
\begin{align*}
    \Delta \mathbf{x}^\top \mathbf{s} &= \Delta \mathbf{x}^\top \mathbf{s} + \Delta \mathbf{x}^\top \Delta \mathbf{s} \\
&= \Delta \mathbf{x}^\top \mathbf{s} - \Delta \mathbf{x}^\top (\mathbf{s} + \tau g(\mathbf{x}) + \tau H(\mathbf{x}) \Delta \mathbf{x}) \\
&= -\tau (\Delta \mathbf{x}^\top g(\mathbf{x}) + \|\Delta \mathbf{x}\|_{\mathbf{x}}^2).
\end{align*}
Similarly, we can express $\mathbf{x}^\top \Delta \mathbf{s}$ as
\begin{align*}
\mathbf{x}^\top \Delta \mathbf{s} &= - \mathbf{x}^\top \left( \mathbf{s} + \tau g(\mathbf{x}) + \tau H(\mathbf{x}) \Delta \mathbf{x} \right) \\
&\stackrel{\ref{prop:lhscb_Hessian},\ref{prop:lhscb_gradient}}{=} -\mathbf{x}^\top \mathbf{s} + \tau \nu + \tau \Delta \mathbf{x}^\top g(\mathbf{x}).
\end{align*}

Combining the previous equations, we can write $(\mathbf{x}^+)^\top \mathbf{s}^+$ as
\begin{align*}
(\mathbf{x}^+)^\top \mathbf{s}^+ &= \mathbf{x}^\top \mathbf{s} - \tau \Delta \mathbf{x}^\top g(\mathbf{x}) - \tau \|\Delta \mathbf{x}\|_{\mathbf{x}}^2 - \mathbf{x}^\top \mathbf{s} + \tau \nu + \tau \Delta \mathbf{x}^\top g(\mathbf{x}) \\
&= \tau (\nu -  \|\Delta \mathbf{x}\|_{\mathbf{x}}^2).
\end{align*}
Using part \ref{sd_prop:second} of Lemma \ref{lemma:sd_properties}, we get
\[ \tau(\nu-\eta^2) \leq (\mathbf{x}^+)^\top \mathbf{s}^+ \leq \tau\nu.  \]

\end{proof}

\begin{proof}
    At the beginning of the $k^{\text{th}}$ iteration, $\tau = \tau_k = (1-\vartheta)^{k-1} \tau_0$. According to Lemma \ref{lemma:DG}, we have
    \[ \mathbf{x}_k^{\top} \mathbf{s}_k  \leq \tau_k \nu = (1-\vartheta)^{k-1} \tau_0 \nu. \]
    We would like to find the smallest $k$ for which  $(1-\vartheta)^{k-1} \tau_0 \nu \leq \varepsilon$ holds, which is equivalent to
    \[ (k-1) \ln (1-\vartheta) + \ln ( \tau_0 \nu ) \leq \ln \varepsilon.\]
    Using the inequality $-\ln(1 - \vartheta) \geq \vartheta$ for $\vartheta \in [0,1)$, we can require the fulfillment of the stronger inequality
    \[ -(k-1) \vartheta + \ln (\tau_0 \nu ) \leq \ln \varepsilon,\]
which is true if
\[
k \geq \frac{1}{\vartheta} \ln \left( \frac{\tau_0 \nu}{\varepsilon} \right) +1
= \frac{2}{\eta} \left( \sqrt{\nu} + 1 \right)  \ln \left(  \frac{\tau_0\nu}{\varepsilon} \right) +1.
\]

\end{proof}

\begin{proposition}[\protect{\cite[Chapters 2--3]{Renegar2001}, \cite[Chapter 5]{Nesterov2018}, and \cite[Lemma 1]{Nesterov2012}}]
    Let $f$ be a $\nu$-SCB for the proper convex cone $\mathcal{K}$, let $\vx\in\K^\circ$, and let $\mathbf{n} (\mathbf{x} ) = - H (\mathbf{x})^{-1} g (\mathbf{x})$ be the (unconstrained) Newton step for $f$ at $\mathbf{x}$.
       \setlist[enumerate,1]{label=\textup{(A\arabic*)}, leftmargin=5em, labelsep=0.5em, itemindent=0pt}
    \begin{enumerate}
        \item \label{prop:scb_NS}
        If $\|\mathbf{n}(\mathbf{x})\|_{\mathbf{x}} < 1$, then $\mathbf{x}^+ := \mathbf{x} + \mathbf{n} (\mathbf{x})$ satisfies
\[
\|\mathbf{n} (\mathbf{x}^+)\|_{\mathbf{x}^+} \leq \left( \frac{\|\mathbf{n}(\mathbf{x})\|_{\mathbf{x}}}{1 - \|\mathbf{n}(\mathbf{x})\|_{\mathbf{x}}} \right)^2.
\]
    \item \label{prop:scb_norm1}
   If $\mathbf{u} \in \mathcal{B}_{\mathbf{x}}(\mathbf{x},1)$, then $\vu\in\K^\circ$, and for all $\mathbf{v} \neq \mathbf{0}$, one has
\[
\frac{\|\mathbf{v}\|_{\mathbf{u}}^*}{\|\mathbf{v}\|_{\mathbf{x}}^*} \leq \frac{1}{1 - \|\mathbf{u} - \mathbf{x}\|_{\mathbf{x}}}.
\]
