(\mathbf{x}^+)^\top \mathbf{s}^+ &= \mathbf{x}^\top \mathbf{s} - \tau \Delta \mathbf{x}^\top g(\mathbf{x}) - \tau \|\Delta \mathbf{x}\|_{\mathbf{x}}^2 - \mathbf{x}^\top \mathbf{s} + \tau \nu + \tau \Delta \mathbf{x}^\top g(\mathbf{x}) \\
&= \tau (\nu -  \|\Delta \mathbf{x}\|_{\mathbf{x}}^2).
\end{align*}
Using part \ref{sd_prop:second} of Lemma \ref{lemma:sd_properties}, we get
\[ \tau(\nu-\eta^2) \leq (\mathbf{x}^+)^\top \mathbf{s}^+ \leq \tau\nu.  \]

\end{proof}

From the third equation of \eqref{eq:NS}, we have
\begin{align*}
    \Delta \mathbf{x}^\top \mathbf{s} &= \Delta \mathbf{x}^\top \mathbf{s} + \Delta \mathbf{x}^\top \Delta \mathbf{s} \\
&= \Delta \mathbf{x}^\top \mathbf{s} - \Delta \mathbf{x}^\top (\mathbf{s} + \tau g(\mathbf{x}) + \tau H(\mathbf{x}) \Delta \mathbf{x}) \\
&= -\tau (\Delta \mathbf{x}^\top g(\mathbf{x}) + \|\Delta \mathbf{x}\|_{\mathbf{x}}^2).
\end{align*}

Similarly, we can express $\mathbf{x}^\top \Delta \mathbf{s}$ as
\begin{align*}
\mathbf{x}^\top \Delta \mathbf{s} &= - \mathbf{x}^\top \left( \mathbf{s} + \tau g(\mathbf{x}) + \tau H(\mathbf{x}) \Delta \mathbf{x} \right) \\
&\stackrel{\ref{prop:lhscb_Hessian},\ref{prop:lhscb_gradient}}{=} -\mathbf{x}^\top \mathbf{s} + \tau \nu + \tau \Delta \mathbf{x}^\top g(\mathbf{x}).
\end{align*}
